#include <WiFi.h>
#define MIC_PIN 4
#define LED_PIN 48

int noiseFloor = 0;
int threshold = 0;
int runningMax = 0;

int readMic() {
  long sum = 0;
  for (int i = 0; i < 8; i++) {
    sum += analogRead(MIC_PIN);
    delayMicroseconds(100);
  }
  return sum / 8;
}

void setColor(int r, int g, int b) {
  neopixelWrite(LED_PIN, r, g, b);
}

void setup() {
  analogReadResolution(12);

  setColor(0, 0, 0);

  delay(300);
  long sum = 0;
  for (int i = 0; i < 100; i++) {
    sum += readMic();
    delay(10);
  }
  noiseFloor = sum / 100;
  threshold = noiseFloor + 150;
}

void loop() {
  int level = readMic();

  if (level > runningMax) {
    runningMax = level;
  }
  runningMax *= 0.95;   // плавно забываем пики

  if (runningMax > threshold) {
    setColor(0, 255, 0);   // громко — зелёный
  } else {
    setColor(255, 0, 0);   // тихо — красный
  }
}
